<template><div class="page-grid"><section class="panel">
<div class="section-row"><div><h3 class="panel-title">医疗记录</h3><p class="panel-subtitle">来自已关联医疗机构的诊疗、检验、检查、体检与处方信息</p></div><div class="tag-row"><span v-for="hospital in linkedHospitals" :key="hospital.name" class="soft-badge">{{hospital.name}}</span></div></div>
<div style="display:flex;gap:10px;align-items:center;margin:8px 0 20px"><el-segmented v-model="filter" :options="filterOptions"/><el-input v-model="keyword" clearable placeholder="搜索记录名称、科室或医疗机构" style="max-width:320px"/></div>
<div style="display:grid;gap:12px"><div v-for="record in filteredRecords" :key="record.id" class="record-card"><div><div class="record-date">{{record.date}}</div><el-tag size="small" effect="plain" style="margin-top:8px">{{record.type}}</el-tag></div><div class="record-main"><h3>{{record.title}}</h3><p>{{record.hospital}}<span v-if="record.department"> · {{record.department}}</span></p><p>{{record.summary}}</p><div class="tag-row" v-if="record.tags?.length" style="margin-top:8px"><span v-for="tag in record.tags" :key="tag" class="soft-badge">{{tag}}</span></div></div><div style="display:grid;gap:8px"><el-button size="small" @click="selectedRecord=record">查看详情</el-button><el-button size="small" type="primary" plain @click="askAbout(record)">AI 解读</el-button></div></div><div v-if="filteredRecords.length===0" class="empty-soft">暂无符合条件的医疗记录</div></div>
</section><el-drawer v-model="drawerVisible" size="520px" :title="selectedRecord?.title"><template v-if="selectedRecord"><el-descriptions :column="1" border><el-descriptions-item label="记录编号">{{selectedRecord.id}}</el-descriptions-item><el-descriptions-item label="日期">{{selectedRecord.date}}</el-descriptions-item><el-descriptions-item label="类型">{{selectedRecord.type}}</el-descriptions-item><el-descriptions-item label="医疗机构">{{selectedRecord.hospital}}</el-descriptions-item><el-descriptions-item label="科室">{{selectedRecord.department||'-'}}</el-descriptions-item></el-descriptions><h4 style="margin:24px 0 10px">记录内容</h4><div v-for="line in selectedRecord.detail" :key="line" style="padding:11px 12px;background:#f7f9f9;border-radius:9px;margin-bottom:8px;font-size:13px">{{line}}</div><el-button type="primary" plain style="margin-top:16px" @click="askAbout(selectedRecord)">使用 AI 健康助手解读</el-button></template></el-drawer>
</div></template>
<script setup lang="ts">import {computed,ref} from 'vue';import {useRouter} from 'vue-router';import {linkedHospitals,medicalRecords,type MedicalRecord} from '@/data/health';const router=useRouter();const filterOptions=['全部','门诊','检验','检查','体检','处方'];const filter=ref('全部');const keyword=ref('');const selectedRecord=ref<MedicalRecord|null>(null);const drawerVisible=computed({get:()=>Boolean(selectedRecord.value),set:(v)=>{if(!v)selectedRecord.value=null}});const filteredRecords=computed(()=>medicalRecords.filter(r=>{const typeOk=filter.value==='全部'||r.type===filter.value;const text=`${r.title}${r.hospital}${r.department??''}${r.summary}`.toLowerCase();return typeOk&&text.includes(keyword.value.trim().toLowerCase())}));function askAbout(record:MedicalRecord){sessionStorage.setItem('assistant-prefill',`请帮我解读 ${record.date} 的《${record.title}》`);router.push('/user/assistant')}</script>
